INSERT INTO `tipo_material` (`id`, `descripcion`, `nombre_material`) VALUES
(1, 'Aleación de hierro y carbono, usado en estructuras y piezas mecánicas', 'Acero al carbono'),
(2, 'Resistente a la corrosión, ideal para tanques, cañerías y utensilios industriales', 'Acero inoxidable'),
(3, 'Material denso y frágil, usado en maquinaria pesada', 'Hierro fundido'),
(4, 'Ligero y resistente, ideal para estructuras y componentes eléctricos', 'Aluminio'),
(5, 'Excelente conductor eléctrico y térmico, usado en cables y tuberías', 'Cobre'),
(6, 'Aleación de cobre y estaño, resistente al desgaste y a la fricción', 'Bronce'),
(7, 'Aleación de cobre y zinc, usada en válvulas y accesorios industriales', 'Latón'),
(8, 'Utilizado para galvanizar metales y prevenir la corrosión', 'Zinc'),
(9, 'Usado en aleaciones resistentes a altas temperaturas', 'Níquel'),
(10, 'Alta resistencia y baja densidad, ideal para piezas de precisión', 'Titanio'),
(11, 'Acero recubierto con zinc, resistente a la intemperie', 'Chapa galvanizada'),
(12, 'Acero tratado térmicamente para aumentar su dureza', 'Acero templado'),
(13, 'Acero con acabado fino y alta precisión dimensional', 'Acero laminado en frío'),
(14, 'Usado para perfiles estructurales y planchuelas', 'Acero laminado en caliente'),
(15, 'Aleación para piezas sometidas a presión y temperatura elevadas', 'Acero al cromo-molibdeno'),
(16, 'Perfil hueco de acero usado en estructuras metálicas', 'Tubo estructural'),
(17, 'Chapa metálica con perforaciones, usada en ventilaciones o filtros', 'Chapa perforada'),
(18, 'Perfil de acero en forma de L para estructuras', 'Perfil angular (L)'),
(19, 'Perfil de acero para soportes y guías', 'Perfil U (canal)'),
(20, 'Varilla de acero o aluminio para ejes y pernos', 'Barra redonda');
